const r = await tools.exec_command({"cmd":"node --input-type=module <<'JS'
import fs from 'node:fs';
const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const target = targets.find(t => t.type === 'page' && t.url.includes('127.0.0.1:4001'));
if (!target) throw new Error('Prototype page target not found');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let nextId = 1;
const pending = new Map();
ws.onmessage = event => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    const {resolve, reject} = pending.get(message.id);
    pending.delete(message.id);
    message.error ? reject(new Error(message.error.message)) : resolve(message.result);
  }
};
function send(method, params = {}) {
  const id = nextId++;
  ws.send(JSON.stringify({id, method, params}));
  return new Promise((resolve, reject) => pending.set(id, {resolve, reject}));
}
await send('Runtime.evaluate', {expression: `document.querySelector('.open-dialog').click(); document.querySelector('#url').value = 'https://www.seriouseats.com/the-best-roast-potatoes-ever-recipe-5217326'; document.querySelector('#bookmark-form').requestSubmit();`});
await new Promise(resolve => setTimeout(resolve, 1200));
const check = await send('Runtime.evaluate', {expression: `JSON.stringify({count: document.querySelector('#count').textContent, title: document.querySelector('.card h2')?.textContent, emptyHidden: document.querySelector('#empty-state').style.display})`, returnByValue: true});
const state = JSON.parse(check.result.value);
if (state.count !== '1 saved' || state.title !== 'The Best Crispy Roast Potatoes Ever' || state.emptyHidden !== 'none') throw new Error('Unexpected final state: ' + JSON.stringify(state));
await send('Emulation.setDeviceMetricsOverride', {width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false});
const shot = await send('Page.captureScreenshot', {format: 'png', captureBeyondViewport: true});
fs.writeFileSync('prototypes/save-bookmark-result.png', Buffer.from(shot.data, 'base64'));
console.log('Prototype check passed:', state);
ws.close();
