    .close {
      border: 0;
      background: transparent;
      color: var(--muted);
      width: 34px;
      height: 34px;
      border-radius: 8px;
      font-size: 23px;
      line-height: 1;
    }

    .close:hover { background: #f2f3ef; }

    form { padding: 4px 26px 26px; }

    label {
      display: block;
      font-size: 13px;
      font-weight: 750;
      margin-bottom: 8px;
    }

    input {
      width: 100%;
      border: 1px solid #cbd1c7;
      border-radius: 10px;
      padding: 12px 13px;
      outline: none;
      color: var(--ink);
      background: white;
    }

    input:focus { border-color: var(--green); box-shadow: 0 0 0 3px rgba(40,89,67,.12); }

    .hint { margin: 8px 0 0; color: var(--muted); font-size: 12px; line-height: 1.45; }

    .dialog-actions {
      display: flex;
      justify-content: flex-end;
      gap: 10px;
      margin-top: 25px;
    }

    .secondary {
      border: 1px solid var(--line);
      border-radius: 10px;
      padding: 10px 16px;
      background: white;
      color: var(--ink);
      font-weight: 650;
    }

    .spinner {
      width: 15px;
      height: 15px;
      border: 2px solid rgba(255,255,255,.45);
      border-top-color: white;
      border-radius: 50%;
      animation: spin .7s linear infinite;
    }

    @keyframes spin { to { transform: rotate(360deg); } }

    @media (max-width: 720px) {
      .shell { width: min(100% - 28px, 1120px); }
      header { height: 72px; }
      header .primary span { display: none; }
      main { padding-top: 32px; }
      .heading { align-items: start; }
      .count { margin-top: 8px; }
      .empty { min-height: 410px; }
      .grid { grid-template-columns: 1fr; }
    }
  </style>
</head>
<body>
  <div class="shell" id="app" data-harness-ready="true">
    <header>
      <div class="brand">
        <span class="brand-mark" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M6 3.8h12v16.4l-6-3.5-6 3.5z"/></svg>
        </span>
        Bookmarks
      </div>
      <button class="primary open-dialog" type="button" aria-label="Add bookmark">
        <b aria-hidden="true">＋</b><span>Add bookmark</span>
      </button>
    </header>

    <main>
      <div class="heading">
        <div>
          <h1>Your collection</h1>
          <p class="subtitle">Everything worth coming back to.</p>
        </div>
        <span class="count" id="count">0 saved</span>
      </div>

      <section class="empty" id="empty-state">
        <div class="empty-inner">
          <div class="illustration" aria-hidden="true">
            <svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="3"><path d="M19 11h26v42L32 45 19 53z"/><path d="M27 25h10M32 20v10" stroke-linecap="round"/></svg>
          </div>
          <h2>Save your first good find</h2>
          <p>Paste a link and its useful details will be brought in for you.</p>
          <button class="primary open-dialog" type="button">Add your first bookmark</button>
        </div>
      </section>

      <section class="grid" id="bookmark-grid" aria-live="polite"></section>
    </main>
  </div>

  <dialog id="add-dialog">
    <div class="dialog-head">
      <div>
        <h2>Add a bookmark</h2>
        <p>Just paste the link. We’ll handle the details.</p>
      </div>
      <button class="close" type="button" aria-label="Close">×</button>
    </div>
    <form id="bookmark-form">
      <label for="url">Web address</label>
      <input id="url" name="url" type="url" placeholder="https://example.com/article" autocomplete="url" required>
      <p class="hint">The page title, description, and site icon will be added automatically.</p>
      <div class="dialog-actions">
        <button class="secondary cancel" type="button">Cancel</button>
        <button class="primary" id="save-button" type="submit">Save bookmark</button>
      </div>
    </form>
  </dialog>

  <script>
    const dialog = document.querySelector('#add-dialog');
    const input = document.querySelector('#url');
    const form = document.querySelector('#bookmark-form');
    const saveButton = document.querySelector('#save-button');
    const emptyState = document.querySelector('#empty-state');
    const grid = document.querySelector('#bookmark-grid');
    const count = document.querySelector('#count');

    document.querySelectorAll('.open-dialog').forEach(button => {
      button.addEventListener('click', () => {
        dialog.showModal();
        requestAnimationFrame(() => input.focus());
      });
    });

    function closeDialog() {
      dialog.close();
      form.reset();
    }

    document.querySelector('.close').addEventListener('click', closeDialog);
    document.querySelector('.cancel').addEventListener('click', closeDialog);
    dialog.addEventListener('click', event => {
      if (event.target === dialog) closeDialog();
    });

    const exampleMetadata = {
      title: 'The Best Crispy Roast Potatoes Ever',
      description: 'These roast potatoes maximize the crisp-to-creamy contrast in every chunk, with a crunchy shell and a fluffy center.',
      site: 'Serious Eats',
      letter: 'S'
    };

    form.addEventListener('submit', event => {
      event.preventDefault();
      if (!form.reportValidity()) return;

      const url = input.value.trim();
      saveButton.disabled = true;
      saveButton.innerHTML = '<span class="spinner" aria-hidden="true"></span> Getting details…';

      window.setTimeout(() => {
        const host = new URL(url).hostname.replace(/^www\./, '');
        const isExample = host.includes('seriouseats.com');
        const metadata = isExample ? exampleMetadata : {
          title: 'A page worth coming back to',
          description: 'The page description has been collected automatically so you can recognize this bookmark later.',
          site: host,
          letter: host.charAt(0).toUpperCase()
        };

        const card = document.createElement('article');
        card.className = 'card';
        card.innerHTML = `
          <div class="site"><span class="favicon">${metadata.letter}</span>${metadata.site}</div>
          <h2>${metadata.title}</h2>
          <p class="description">${metadata.description}</p>
          <div class="url">${url}</div>
        `;

        grid.replaceChildren(card);
        emptyState.style.display = 'none';
        grid.style.display = 'grid';
        count.textContent = '1 saved';
        saveButton.disabled = false;
        saveButton.textContent = 'Save bookmark';
        dialog.close();
        form.reset();
      }, 800);
    });
  </script>
</body>
</html>

