import fs from'node:fs';const ts=await(await fetch('http://127.0.0.1:9235/json')).json(),t=ts.find(x=>x.type==='page'),ws=new WebSocket(t.webSocketDebuggerUrl);await new Promise((r,j)=>{ws.onopen=r;ws.onerror=j});let id=1;const p=new Map;ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&p.has(m.id)){p.get(m.id)(m.result);p.delete(m.id)}};const send=(method,params={})=>{const n=id++;ws.send(JSON.stringify({id:n,method,params}));return new Promise(r=>p.set(n,r))};const ev=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true})).result.value;const wait=m=>new Promise(r=>setTimeout(r,m));await ev(`document.querySelector('#select-toggle').click();for(const c of document.querySelectorAll('.card')){const t=c.querySelector('h2').textContent;if(t.includes('Potatoes')||t.includes('Kyoto'))c.querySelector('[data-bulk-select]').click()}document.querySelector('#bulk-add-label').click();document.querySelector('input[name="bulk-label"][value="Work"]').click();document.querySelector('#bulk-label-apply').click()`);await wait(350);const s=JSON.parse(await ev(`JSON.stringify([...document.querySelectorAll('.card')].filter(c=>c.querySelector('h2').textContent.includes('Potatoes')||c.querySelector('h2').textContent.includes('Kyoto')).map(c=>[...c.querySelectorAll('.tag')].map(x=>x.textContent)))`));if(s.length!==2||!s.every(labels=>labels.includes('Work')&&labels.length===2))throw Error(JSON.stringify(s));const shot=await send('Page.captureScreenshot',{format:'png',captureBeyondViewport:true});fs.writeFileSync('prototypes/bulk-add-label.png',Buffer.from(shot.data,'base64'));console.log('Bulk label flow passed:',s);ws.close();
