    function renderCard(url, metadata, finalTitle, finalDescription) {
      const card = document.createElement('article');
      card.className = 'card';
      card.innerHTML = `
        <div class="site"><span class="favicon">${metadata.letter}</span>${metadata.site}</div>
        <h2>${finalTitle}</h2>
        <p class="description">${finalDescription}</p>
        ${currentLabels.length ? `<div class="bookmark-tags">${currentLabels.map(label => `<span class="label-pill">${label}</span>`).join('')}</div>` : ''}
        <div class="url">${url}</div>
      `;

      if (manageMode === 'direct') {
        const manage = document.createElement('div');
        manage.className = 'card-manage';
        manage.innerHTML = `<button class="edit-direct" type="button">Edit</button>${deleteMode === 'direct' ? '<button class="delete-direct" type="button">Delete</button>' : ''}`;
        manage.querySelector('.edit-direct').addEventListener('click', openExistingEditor);
        manage.querySelector('.delete-direct')?.addEventListener('click', openDeleteDialog);
        card.append(manage);
      } else if (manageMode === 'menu') {
        const manage = document.createElement('div');
        manage.className = 'card-manage';
        manage.innerHTML = '<button class="more-button" type="button" aria-label="Bookmark actions">•••</button><div class="card-menu"><button type="button">Edit bookmark</button></div>';
        const menu = manage.querySelector('.card-menu');
        manage.querySelector('.more-button').addEventListener('click', () => menu.classList.toggle('visible'));
        menu.querySelector('button').addEventListener('click', openExistingEditor);
        card.append(manage);
      }

      grid.replaceChildren(card);
      emptyState.style.display = 'none';
      grid.style.display = 'grid';
      count.textContent = '1 saved';
    }

    function addDraftLabel(value) {
      const label = value.trim();
      if (!label || draftLabels.some(item => item.toLowerCase() === label.toLowerCase())) return;
      draftLabels.push(label);
      setupLabelEditor(true);
    }

    function setupLabelEditor(focusNew = false) {
      const section = document.querySelector('#label-editor');
      const content = document.querySelector('#label-editor-content');
      section.classList.add('visible');
      if (!draftLabels.length) draftLabels = [...currentLabels];

      if (labelMode === 'type') {
        content.innerHTML = `<div class="selected-labels">${draftLabels.map(label => `<span class="label-pill">${label}</span>`).join('')}</div><input id="new-label" type="text" placeholder="Type a new label"><p class="label-hint">Press Enter to add another label.</p>`;
        const newLabel = document.querySelector('#new-label');
        newLabel.addEventListener('keydown', event => {
          if (event.key !== 'Enter') return;
          event.preventDefault();
          addDraftLabel(newLabel.value);
        });
        if (focusNew) newLabel.focus();
      } else {

      saveButton.disabled = true;
      saveButton.innerHTML = '<span class="spinner" aria-hidden="true"></span> Getting details…';

      window.setTimeout(() => {
        const metadata = detailsFor(url);
        if (mode === 'guided') {
          showEditableDetails(metadata);
          return;
        }
        saveCard(url, metadata);
      }, 800);
    });

    if (manageMode) {
      currentUrl = 'https://www.seriouseats.com/the-best-roast-potatoes-ever-recipe-5217326';
      currentMetadata = {...exampleMetadata};
      currentTitle = exampleMetadata.title;
      currentDescription = exampleMetadata.description;
      currentLabels = labelMode ? ['Recipes'] : [];
      renderCard(currentUrl, currentMetadata, currentTitle, currentDescription);
    }
  </script>
</body>
</html>

