const r = await tools.exec_command({cmd:"node <<'JS'
const { chromium } = require('playwright');
(async()=>{
  const url='http://127.0.0.1:4001/search.html?mode=live&labels=chips&readLater=check&archive=true&empty=collection';
  const browser=await chromium.launch({headless:true, executablePath:'/opt/playwright-browsers/chromium-1194/chrome-linux/chrome'});
  const page=await browser.newPage({viewport:{width:1440,height:900}});
  await page.goto(url,{waitUntil:'networkidle'});
  await page.locator('[data-harness-ready="true"]').waitFor();
  if(await page.locator('#count').innerText()!=='0 saved') throw new Error('incorrect count');
  if(await page.locator('#empty-content strong').innerText()!=='No bookmarks yet') throw new Error('incorrect empty heading');
  if(await page.locator('#search-form').isVisible()) throw new Error('search visible');
  if(!await page.locator('.empty-action').isVisible()) throw new Error('empty action missing');
  await page.screenshot({path:'prototypes/empty-collection.png',fullPage:true});
  console.log(await page.locator('#empty-content').innerText());
