+    }
+    this.db.prepare('DELETE FROM bookmark_labels WHERE bookmark_id = ?').run(bookmarkId);
+    const attach = this.db.prepare('INSERT OR IGNORE INTO bookmark_labels(bookmark_id, label_id) VALUES (?, ?)');
+    for (const name of unique) {
