:root {
  --ink: #1d2736;
  --muted: #697384;
  --line: #dfe3e8;
  --line-strong: #c9d0d9;
  --paper: #f7f5f0;
  --surface: #ffffff;
  --navy: #223046;
  --navy-hover: #172235;
  --blue-soft: #eaf0f7;
  --accent: #c45f3c;
  --accent-soft: #faebe5;
  --danger: #a43c35;
  --danger-soft: #fceceb;
  --success: #316b50;
  --success-soft: #e7f1eb;
  --shadow: 0 14px 38px rgba(31, 42, 56, .09);
