.button-secondary:hover:not(:disabled) { border-color: #aeb8c5; background: #f9fafb; }
.button-danger { color: white; background: var(--danger); }
.button-danger-text { color: var(--danger); border-color: transparent; background: transparent; }
.button-danger-text:hover { background: var(--danger-soft); }
.button-on-dark { color: white; border-color: rgba(255,255,255,.24); background: transparent; }
